const axios = require('axios');
const querystring = require('querystring');
const apiToken = "";  // 请替换为实际API令牌（非passkey），https://tjupt.org/usercp.php?action=user_api_token
const MAX_HASH_COUNT = 35; // 每次请求的最大hash数量
const COMPLETE_CATEGORY = "TJU_Complete";
const KEEP_CATEGORY = "TJU";
const TJU_CATEGORY = "TJU";
async function getHashes() {
    const clients = {};

    Object.entries(global.runningClient).forEach(([key, client]) => {
        if (!client.maindata || !client.maindata.torrents) {
            logger.warn(`下载器：${client.alias} 中没有找到种子信息`);
            return; // 如果没有torrents，跳过这个客户端
        }

        const tjuTorrents = [];
        // 状态为下载完成的种子
        for (const torrent of client.maindata.torrents) {
            if (torrent.category === TJU_CATEGORY) {
                logger.info(`种子：${torrent.name} 上传量：${torrent.uploaded} 下载量：${torrent.size} 上传速度：${torrent.uploadSpeed} 状态：${torrent.state}`);
                if (torrent.state === 'stalledUP' || torrent.state === 'forcedUP' || torrent.state === 'pausedUP' || torrent.state === 'uploading') {
                    tjuTorrents.push(torrent.hash);
                }
            }
        }

        if (tjuTorrents.length > 0) {
            logger.info(`下载器：${client.alias} 中tju分类种子数量：${tjuTorrents.length}`);

            clients[client.id] = {
                url: client.clientUrl,
                clientCookie: client.cookie,
                torrents: tjuTorrents
            };
        }
    });

    return clients;
}


async function setTorrentsCategory(clientUrl, cookie, hashes, category) {
    const path = "/api/v2/torrents/setCategory";
    const apiUrl = clientUrl + path;
    const headers = { 'Cookie': cookie, 'Content-Type': 'application/x-www-form-urlencoded; charset=UTF-8', 'Accept': 'text/javascript, text/html, application/xml, text/xml, */*' };

    const getRequest = async (url) => {
        return axios.get(url, { headers }).then(response => response.data);
    };

    logger.info(`设置分类：${category} 到种子：${hashes.join('|')}`);

    const setCategory = async () => {
        try {
            const hashesStr = hashes.join('|');
            await axios.post(apiUrl, querystring.stringify({
                hashes: hashesStr,
                category: category
            }), { headers });


        } catch (error) {
            handleSetCategoryError(error);
        }
    };

    const handleSetCategoryError = async (error) => {
        logger.info('设置分类错误:', error.message, error);

        // 检查错误代码是否是 409 - 分类不存在
        if (error.response && (error.response.status === 409 || error.response.status === 400)) {
            try {
                const categories = await getRequest(`${clientUrl}/api/v2/torrents/categories`);
                logger.info('分类列表:', categories);

                if (!categories[category]) {
                    logger.info(`分类 "${category}" 不存在，创建中...`);

                    await axios.post(`${clientUrl}/api/v2/torrents/createCategory`, querystring.stringify({
                        category: category
                    }), { headers });

                    logger.info('分类创建成功.');

                    // 重试设置分类
                    await setCategory();
                } else {
                    logger.info('分类存在，但其他问题导致设置错误:', error.message);
                }
            } catch (catError) {
                logger.info('分类列表或创建过程出错:', catError.message);
            }
        }
    };

    // 执行设置分类的流程
    await setCategory();
}


function parseHR(result) {
    // 0	未触发？？？？？？
    // 1	24h等待期
    // 5	下载考核中
    // 6	下载考核中(过半)
    // 10	做种考核中
    // 11	做种考核中(过半)
    // 12	未达标
    // 20	已达标
    // 21	后达标
    // 40	种子被删取消
    // 41	未成功下载取消
    // 42	管理员取消
    // 43	自行放弃
    // 44	冗余考核
    const completeStatusCodes = [20, 21, 40, 41, 42, 43, 44];
    try {
        // 达标种子hash
        const completeTorrentHashes = [];
        // 未达标种子hash
        const otherTorrentHashes = [];

        for (const item of result.data) {
            logger.info('种子信息:', item.torrent.name, item.torrent.info_hash, item.status.hnr_status, item.status.hnr_status_code);
            if (completeStatusCodes.includes(item.status.hnr_status_code)) {
                completeTorrentHashes.push(item.torrent.info_hash);
                logger.info('达标种子:' + item.status.hnr_status + item.status.hnr_status_code + ' ' + item.torrent.name);
            } else {
                logger.info('未达标种子:' + item.status.hnr_status + item.status.hnr_status_code + ' ' + item.torrent.name);
                otherTorrentHashes.push(item.torrent.info_hash);
            }
        }

        return {
            completeTorrentHashes: completeTorrentHashes,
            otherTorrentHashes: otherTorrentHashes
        };

    } catch (e) {
        return null;
    }
}



async function getTorrents(hashes) {
    const hnrUrl = "https://tjupt.org/api/v1/hnr.php";

    const headers = {
        'Content-Type': 'application/json',
        'Authorization': 'Bearer ' + apiToken
    };

    const data = {
        "info_hash": hashes
    };
    logger.info('请求数据:', data);

    try {
        const response = await axios.post(hnrUrl, data, { headers });
        logger.info('响应数据:', response.data);
        const result = response.data;
        const parsedResult = parseHR(result);
        return parsedResult;
    } catch (error) {
        throw new Error('请求错误: ' + error.message);
    }
}



(async () => {

    // 使用 await 关键字等待 getHashes 返回的结果
    const tjuHashByClient = await getHashes();
    const hashes = Object.values(tjuHashByClient).flatMap(client => client.torrents);

    if (hashes.length === 0) {
        return logger.info('没有种子');
    }

    const hashGroups = [];
    for (let i = 0; i < hashes.length; i += MAX_HASH_COUNT) {
        hashGroups.push(hashes.slice(i, i + MAX_HASH_COUNT));
    }
    logger.info('分组后的hash:', hashGroups);


    // 达标种子hash
    const totalCompleteTorrentHashes = [];
    // 未达标种子hash
    const totalOtherTorrentHashes = [];

    for (const hashGroup of hashGroups) {
        try {
            const result = await getTorrents(hashGroup);
            // 获得达标种子hash
            const completeTorrentHashes = result.completeTorrentHashes;
            // 获得未达标种子hash
            const otherTorrentHashes = result.otherTorrentHashes;
            totalCompleteTorrentHashes.push(...completeTorrentHashes);
            totalOtherTorrentHashes.push(...otherTorrentHashes);

            // logger.info('响应数据:', result);
            logger.info('响应数据:', result);
        } catch (error) {
            // console.error('发生错误:', error.message);
            logger.error('发生错误:', error.message);
        }
    }

    // 遍历下载器种子hash，获得每个下载器中达标的种子
    for (const [key, clientData] of Object.entries(tjuHashByClient)) {
        const completeTorrentHashes = [];
        const otherTorrentHashes = [];

        for (const hash of clientData.torrents) {
            (totalCompleteTorrentHashes.includes(hash) ? completeTorrentHashes : otherTorrentHashes).push(hash);
        }

        if (completeTorrentHashes.length > 0) {
            await setTorrentsCategory(clientData.url, clientData.clientCookie, completeTorrentHashes, COMPLETE_CATEGORY);
        }

        if (otherTorrentHashes.length > 0) {
            await setTorrentsCategory(clientData.url, clientData.clientCookie, otherTorrentHashes, KEEP_CATEGORY);
        }
    }


})();

