(maindata, torrent) => {
  const { size, category, uploaded, downloaded, upspeed, downspeed, progress, num_seeds, num_leechs } = torrent.originProp;

  // 检查种子类别是否包含 "TJU"
  if (!category.includes("TJU")) {
    return false; // 不删除
  }

  // 计算分享率
  const ratio = downloaded > 0 ? uploaded / downloaded : 0;

  // 进度检查，根据不同大小的种子设置不同的进度范围
  if (size <= util.calSize(10, "GiB")) {
    if (progress < 0.085 || progress > 0.090) {
      return false; // 不删除
    }
  } else if (size <= util.calSize(20, "GiB")) {
    if (progress < 0.085 || progress > 0.090) {
      return false; // 不删除
    }
  } else if (size <= util.calSize(30, "GiB")) {
    if (progress < 0.088 || progress > 0.090) {
      return false; // 不删除
    }
  } else if (size <= util.calSize(40, "GiB")) {
    if (progress < 0.089 || progress > 0.091) {
      return false; // 不删除
    }
  } else if (size <= util.calSize(50, "GiB")) {
    if (progress < 0.090 || progress > 0.092) {
      return false; // 不删除
    }
  } else {
    if (progress < 0.090 || progress > 0.096) {
      return false; // 不删除
    }
  }

  // 特殊条件检查
  // 如果种子大小小于10 GiB且分享率大于等于1，则不删除
  if (size < util.calSize(10, "GiB") && ratio >= 1) {
    return false; // 不删除
  } 
  // 如果种子大小小于20 GiB，做种数量是吸血者数量的3倍且分享率大于等于2.5，上传速度大于等于下载速度，则不删除
  else if (size < util.calSize(20, "GiB") && num_seeds >= 3 * num_leechs && ratio >= 2.5 && upspeed >= downspeed) {
    return false; // 不删除
  } 
  // 删除条件
  else if (
    (size < util.calSize(10, "GiB") && upspeed < util.calSize(500, "KiB")) || // 小于10 GiB且上传速度小于500 KiB/s
    (size >= util.calSize(10, "GiB") && upspeed < util.calSize(1, "MiB") && num_seeds >= num_leechs && (upspeed <= downspeed || ratio < 1)) || // 大于等于10 GiB且上传速度小于1 MiB/s且做种数量大于等于吸血者数量，且（上传速度小于等于下载速度，或分享率小于1）
    ((size > 0 && size < util.calSize(8, "GiB")) || // 大小在0到8 GiB之间
     (size > util.calSize(10, "GiB") && size <= util.calSize(13, "GiB") && ratio <= 2.0 && uploaded <= downloaded)) // 大小在10到13 GiB之间且分享率小于等于2.0且上传量小于等于下载量
  ) {
    return true; // 删除
  }

  return false; // 默认不删除
};

