        logger.info(`下载器：${client.alias} 计算可用空间：${(availableDiskSpace/1024/1024/1024).toFixed(2)}GB`);

        if (availableDiskSpace > size) {
            logger.info("剩余空间满足，添加种子！");
            client.addTorrent(
                url,
                hash,
                false,
                uploadLimit,
                downloadLimit,
                savePath,
                this.category,
                this.autoTMM,
                this.paused
            );

            util.runRecord('INSERT INTO torrents (hash, name, size, rss_id, link, category, record_time, add_time, record_type, record_note) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)',
                [hash, name, size, this.id, link, this.category, moment().unix(), moment().unix(), 1, '添加种子']);

            break; // 添加成功，终止执行
        } else {
            logger.info(`下载器 ${client.alias} 剩余空间不足（需要 ${(size/1024/1024/1024).toFixed(2)}GB），跳过`);

        }
    }

    return false;
}

(torrent) => {
const { id } = torrent;
const minId = 0; // 填当前站老种分界 id，0 表示不按 id 拒绝
    if (minId && id < minId) {
return true;
}
return false;
};
